const raw = $json;
let text = '';
if (typeof raw.text === 'string' && raw.text.trim()) text = raw.text.trim();
else if (typeof raw.output === 'string' && raw.output.trim()) text = raw.output.trim();
else if (raw.content?.[0]?.text) text = String(raw.content[0].text).trim();
else if (raw['0']?.content?.[0]?.text) text = String(raw['0'].content[0].text).trim();
else if (Array.isArray(raw) && raw[0]?.content?.[0]?.text) text = String(raw[0].content[0].text).trim();
if (!text) text = 'Не удалось распознать изображение';
return [{ json: { message: { text }, sessionId: $('Text Or Voice2').item.json.message.chat.id } }];

// n8n Code node (JS)

return items.map(item => {
  const raw = item.json.payload;

  let obj;

  // payload может быть строкой (JSON) или уже объектом
  if (raw == null) {
    obj = {};
  } else if (typeof raw === 'string') {
    try {
      obj = JSON.parse(raw);
    } catch (e) {
      // если строка не JSON — считаем, что это и есть текст
      obj = { text: raw };
    }
  } else if (typeof raw === 'object') {
    obj = raw;
  } else {
    obj = { text: String(raw) };
  }

  const text = (obj.text ?? '').toString().trim();

  return {
    json: { text }
  };
});

// Code node (Run Once for All Items)

const data = $input.first().json;

const prev = (data.agg ?? '').toString().trim();
const line = (data.text ?? '').toString().trim();

const combined = prev
  ? (line ? `${prev}\n${line}` : prev)
  : line;

return [{ json: { combined } }];

const root = $json.body ?? $json ?? {};

function buildNames(fullName) {
  const cleaned = String(fullName || '').trim();
  const parts = cleaned.split(/\s+/).filter(Boolean);
  return {
    firstName: parts[0] || '',
    lastName: parts.slice(1).join(' '),
  };
}

function buildCallback(chatId, callbackData, callbackLabel, raw) {
  return [{
    json: {
      callback_query: {
        id: String(Date.now()) + '_' + Math.random().toString(36).slice(2, 8),
        from: { id: chatId },
        data: callbackData,
        message: {
          message_id: Date.now(),
          chat: { id: chatId },
          reply_markup: {
            inline_keyboard: [[{ text: callbackLabel || 'Ответ' }]],
          },
        },
      },
      wa_raw: raw,
    },
  }];
}

function normalizeSignal(rawSignal) {
  const signal = String(rawSignal || '').trim();
  const lower = signal.toLowerCase();

  let callbackData = '';
  let callbackLabel = '';

  const pipeMatch = signal.match(/^(confirm|reschedule|cancel)\|(\d+)\|(1h|2h|12h|24h)$/i);
  if (pipeMatch) {
    callbackData = pipeMatch[1].toLowerCase() + '|' + pipeMatch[2] + '|' + pipeMatch[3].toLowerCase();
    callbackLabel = 'Подтверждение записи';
  }

  if (!callbackData) {
    const ruMatch = signal.match(/^(приду|подтверждаю|перенести|не\s*смогу|отмена)\s+(\d+)\s*(1h|2h|12h|24h)$/i);
    if (ruMatch) {
      const map = {
        'приду': 'confirm',
        'подтверждаю': 'confirm',
        'перенести': 'reschedule',
        'не смогу': 'cancel',
        'отмена': 'cancel',
      };
      callbackData = map[ruMatch[1].toLowerCase()] + '|' + ruMatch[2] + '|' + ruMatch[3].toLowerCase();
      callbackLabel = ruMatch[1];
    }
  }

  if (!callbackData && (lower === 'marketing_agree' || /подтверждаю\s+соглашение/i.test(signal) || lower === 'согласен')) {
    callbackData = 'marketing_agree';
    callbackLabel = 'Подтверждаю соглашение';
  }

  return { signal, lower, callbackData, callbackLabel };
}

function buildMessagePayload({ chatId, fullName, text, raw, mediaType = '', mediaId = '', caption = '' }) {
  const { firstName, lastName } = buildNames(fullName);
  const message = {
    message_id: Date.now(),
    from: {
      id: chatId,
      first_name: firstName,
      last_name: lastName,
      username: chatId,
    },
    chat: {
      id: chatId,
      first_name: firstName,
      last_name: lastName,
      username: chatId,
    },
    date: Math.floor(Date.now() / 1000),
  };

  if (text) message.text = text;
  if (caption) message.caption = caption;
  if (mediaType === 'audio' && mediaId) message.voice = { file_id: mediaId };
  if (mediaType === 'image' && mediaId) message.photo = [{ file_id: mediaId }];

  return [{ json: { message, wa_raw: raw } }];
}

// Green-API payload
if (root.typeWebhook || root.senderData || root.messageData) {
  if (root.typeWebhook !== 'incomingMessageReceived') return [];

  const sender = root.senderData || {};
  const messageData = root.messageData || {};
  const typeMessage = String(messageData.typeMessage || '').trim();
  const chatId = String(sender.chatId || '').trim();
  if (!chatId) return [];

  const fullName = String(sender.senderName || sender.chatName || '').trim();
  const idMessage = String(root.idMessage || '').trim();
  const caption = String(messageData.fileMessageData?.caption || '').trim();
  const buttonReplyId = String(
    messageData.templateButtonReplyMessage?.selectedId ||
    messageData.buttonsResponseMessage?.selectedButtonId ||
    messageData.interactiveButtonsReply?.selectedId ||
    ''
  ).trim();
  const buttonReplyText = String(
    messageData.templateButtonReplyMessage?.selectedDisplayText ||
    messageData.buttonsResponseMessage?.selectedButtonText ||
    messageData.interactiveButtonsReply?.selectedDisplayText ||
    ''
  ).trim();
  const textBody = String(
    buttonReplyText ||
    messageData.textMessageData?.textMessage ||
    messageData.extendedTextMessageData?.text ||
    caption ||
    ''
  ).trim();

  const { signal, callbackData, callbackLabel } = normalizeSignal(buttonReplyId || textBody);
  if (callbackData) return buildCallback(chatId, callbackData, callbackLabel, root);

  let text = signal;
  if (/^(start|старт)$/i.test(text)) text = '/start';

  if (typeMessage === 'audioMessage') {
    return buildMessagePayload({
      chatId,
      fullName,
      text: caption,
      raw: root,
      mediaType: 'audio',
      mediaId: idMessage,
      caption,
    });
  }

  if (typeMessage === 'imageMessage') {
    return buildMessagePayload({
      chatId,
      fullName,
      text: caption,
      raw: root,
      mediaType: 'image',
      mediaId: idMessage,
      caption,
    });
  }

  return buildMessagePayload({
    chatId,
    fullName,
    text: text || 'Пустое сообщение',
    raw: root,
    caption,
  });
}

// Fallback for WhatsApp Cloud / generic payloads
const wa = root.entry?.[0]?.changes?.[0]?.value || root.value || root;
const msg = wa.messages?.[0] || root.messages?.[0] || null;
const contact = wa.contacts?.[0] || root.contacts?.[0] || null;
const chatId = String(msg?.from || contact?.wa_id || root.from || root.chat_id || '').trim();
if (!chatId) return [];

const fullName = String(contact?.profile?.name || contact?.name || root.name || '').trim();
const textBody = String(
  msg?.text?.body ||
  msg?.button?.text ||
  msg?.interactive?.button_reply?.title ||
  msg?.interactive?.list_reply?.title ||
  root.text ||
  ''
).trim();
const buttonPayload = String(
  msg?.button?.payload ||
  msg?.interactive?.button_reply?.id ||
  msg?.interactive?.list_reply?.id ||
  ''
).trim();
const signal = (buttonPayload || textBody).trim();
const normalized = normalizeSignal(signal);
if (normalized.callbackData) return buildCallback(chatId, normalized.callbackData, normalized.callbackLabel, root);

let text = normalized.signal;
if (/^(start|старт)$/i.test(text)) text = '/start';
return buildMessagePayload({ chatId, fullName, text: text || 'Пустое сообщение', raw: root });

const first = $input.first();
if (!first?.json) return [];

const raw = first.json;
const cq = raw.callback_query ?? raw;

const callbackData = String(cq?.data ?? '').trim();
if (!callbackData) return [];
if (!cq?.id || !cq?.message?.chat?.id || !cq?.message?.message_id) return [];

const reminderMap = {
  '24h': 'reminder_24h',
  '12h': 'reminder_12h',
  '2h': 'reminder_2h',
  '1h': 'reminder_1h'
};

let action = '';
let recordIdRaw = '';
let reminderKey = '';

if (callbackData.includes('|')) {
  const parts = callbackData.split('|');
  if (parts.length !== 3) return [];
  [action, recordIdRaw, reminderKey] = parts;
  if (!Object.prototype.hasOwnProperty.call(reminderMap, reminderKey)) return [];
} else if (callbackData.includes('_')) {
  const underscoreIdx = callbackData.indexOf('_');
  action = callbackData.substring(0, underscoreIdx);
  recordIdRaw = callbackData.substring(underscoreIdx + 1);
  reminderKey = '';
} else {
  return [];
}

if (!['confirm', 'reschedule', 'cancel'].includes(action)) return [];

const recordId = Number(recordIdRaw);
if (!Number.isFinite(recordId)) return [];

return [{
  json: {
    query_id: cq.id,
    chat_id: String(cq.message.chat.id),
    message_id: cq.message.message_id,
    action,
    reminder_key: reminderKey,
    reminder_column: reminderMap[reminderKey] || '',
    record_id: recordId
  }
}];

const cb = $('Разобрать callback').all()[0]?.json;
if (!cb) return [];

const appt = $input.first()?.json;
if (!appt?.record_id) return [];

const tz = 'Europe/Moscow';
const dt = new Date(appt.date);
const dateFormatted = Number.isNaN(dt.getTime())
  ? String(appt.date || '')
  : dt.toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', timeZone: tz }) + ' в ' + dt.toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: tz });

const actionToValues = {
  confirm: { reminder_value: 'confirmed_tg', status_value: 'confirmed', attendance: 2, comment_suffix: 'Подтверждено клиентом в Telegram' },
  reschedule: { reminder_value: 'rescheduled_tg', status_value: 'rescheduled', attendance: 0, comment_suffix: 'Клиент запросил перенос через Telegram' },
  cancel: { reminder_value: 'cancelled_tg', status_value: 'cancelled', attendance: -1, comment_suffix: 'Клиент отменил запись через Telegram' }
};

const picked = actionToValues[cb.action];
if (!picked) return [];

let reminderColumn = String(cb.reminder_column || '').trim();
if (!reminderColumn) {
  const candidates = ['reminder_1h', 'reminder_2h', 'reminder_12h', 'reminder_24h']
    .filter((col) => String(appt[col] || '').trim() === 'sent_tg_waiting_response');
  if (candidates.length === 1) reminderColumn = candidates[0];
  else return [];
}

const ycIdRaw = String(appt.YC_ID || '').trim();
const yclientsRecordId = /^\d+$/.test(ycIdRaw) ? ycIdRaw : '';
const yDate = Number.isNaN(dt.getTime())
  ? String(appt.date || '')
  : (() => {
      const parts = new Intl.DateTimeFormat('sv-SE', {
        timeZone: 'Europe/Moscow',
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
      }).formatToParts(dt).reduce((acc, p) => { acc[p.type] = p.value; return acc; }, {});
      return parts.year + '-' + parts.month + '-' + parts.day + ' ' + parts.hour + ':' + parts.minute + ':' + parts.second;
    })();

const serviceId = Number(appt.service_id || 0);
const staffId = Number(appt.master_id || 0);
const durationSec = Math.max(300, Number(appt.duration_min || 60) * 60);
const phone = String(appt.phone || '').replace(/\D/g, '');
const clientName = String(appt.clientName || 'Клиент').trim() || 'Клиент';

const yBody = {
  staff_id: staffId,
  services: serviceId ? [{ id: serviceId }] : [],
  datetime: yDate,
  seance_length: durationSec,
  attendance: picked.attendance,
  comment: [String(appt.comment || '').trim(), picked.comment_suffix].filter(Boolean).join(' | ')
};
if (phone) yBody.client = { phone, name: clientName };

return [{
  json: {
    ...cb,
    reminder_column: reminderColumn,
    date_formatted: dateFormatted,
    service_name: String(appt.service_name || ''),
    yclients_record_id: yclientsRecordId,
    yclients_put_body: yBody,
    reminder_value: picked.reminder_value,
    status_value: picked.status_value
  }
}];

const assistantText = String($json.output ?? $json.result?.text ?? '').trim();
const chatId = String($json.result?.chat?.id ?? $('Merge2').item.json.sessionId ?? '').trim();
const userText = String($('Redis6').item.json.prompt ?? '').trim();

const sentAt = new Date();
const dueAt = new Date(sentAt.getTime() + 60 * 60 * 1000);

const openPatterns = [
  /(^|\s)(подскажите|уточните|напишите|сообщите|выберите|подтвердите|пришлите)(\s|$)/i,
  /(какая|какой|какое|когда|во сколько|на какую|на какой|куда|как вам|удобно\s+ли)/i,
  /(подтвердите\s+(запись|время|дату))/i,
  /(выберите\s+вариант)/i,
  /(как\s+к\s+вам\s+обращаться)/i,
];

const terminalPatterns = [
  /спасибо\s+за\s+обращение/i,
  /обращайт(е|есь)/i,
  /всего\s+доброго/i,
  /хорош(его|ий)\s+(дня|вечера|утра)/i,
  /до\s+свидания/i,
  /до\s+встречи/i,
  /жд[её]м\s+вас/i,
  /(запись|встреча)\s+(подтверждена|оформлена|создана|отменена|перенесена)/i,
  /я\s+все\s+зафиксировала/i,
  /готово/i,
];

const courtesyQuestionPatterns = [
  /(если\s+.*(вопрос|понадоб))/i,
  /(чем\s+ещ[её]\s+могу\s+помочь)/i,
  /(нужна\s+ли\s+еще\s+помощь)/i,
];

const hasQuestionMark = /[?？]/.test(assistantText);
const hasOpenPattern = openPatterns.some((r) => r.test(assistantText));
const hasTerminalPattern = terminalPatterns.some((r) => r.test(assistantText));
const isCourtesyQuestion = courtesyQuestionPatterns.some((r) => r.test(assistantText));

let needsFollowUp = null;
let decisionSource = 'uncertain';

if (!chatId || !assistantText) {
  needsFollowUp = false;
  decisionSource = 'invalid_payload';
} else if (hasTerminalPattern && !hasOpenPattern && (!hasQuestionMark || isCourtesyQuestion)) {
  needsFollowUp = false;
  decisionSource = 'rules_closed';
} else if ((hasOpenPattern || hasQuestionMark) && !isCourtesyQuestion) {
  needsFollowUp = true;
  decisionSource = 'rules_open';
}

return [{
  json: {
    ...$json,
    anti_ignore: {
      chat_id: chatId,
      user_message: userText,
      assistant_message: assistantText,
      needs_follow_up: needsFollowUp,
      decision_source: decisionSource,
      token: chatId + ':' + sentAt.getTime() + ':' + Math.random().toString(36).slice(2, 10),
      sent_at: sentAt.toISOString(),
      due_at: dueAt.toISOString(),
    },
  },
}];

const raw = $json.pending;
let state = null;

if (typeof raw === 'string' && raw.trim() !== '') {
  try {
    state = JSON.parse(raw);
  } catch (error) {
    state = null;
  }
} else if (raw && typeof raw === 'object') {
  state = raw;
}

const expectedToken = String($json.anti_ignore && $json.anti_ignore.token ? $json.anti_ignore.token : '');
const actualToken = String(state && state.token ? state.token : '');

return [{
  json: {
    ...$json,
    anti_ignore_state: state,
    anti_ignore_should_send: Boolean(expectedToken && actualToken && expectedToken === actualToken),
  },
}];

const base = $('Анти-игнор: оценить ответ').item.json;

function extractJson(text) {
  if (!text) return null;
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) return null;
  const candidate = text.slice(start, end + 1);
  try {
    return JSON.parse(candidate);
  } catch (e) {
    return null;
  }
}

let parsed = null;
if ($json && typeof $json === 'object') {
  if (typeof $json.text === 'string') parsed = extractJson($json.text);
  if (!parsed && typeof $json.output === 'string') parsed = extractJson($json.output);
  if (!parsed && typeof $json.response === 'string') parsed = extractJson($json.response);
  if (!parsed && typeof $json.answer === 'string') parsed = extractJson($json.answer);
}

let needs = null;
if (parsed && typeof parsed.needs_follow_up === 'boolean') {
  needs = parsed.needs_follow_up;
}

const confidenceRaw = parsed && parsed.confidence !== undefined ? Number(parsed.confidence) : NaN;
const confidence = Number.isFinite(confidenceRaw) ? confidenceRaw : null;

// conservative fallback: if LLM output is broken or low confidence, do not send reminder
if (needs === null) {
  needs = false;
}
if (confidence !== null && confidence < 0.55) {
  needs = false;
}

return [{
  json: {
    ...base,
    anti_ignore: {
      ...base.anti_ignore,
      needs_follow_up: needs,
      decision_source: 'llm',
      llm: parsed || { parse_error: true },
      llm_confidence: confidence,
    },
  },
}];
